// Translating the docs above into actual fetch() calls

const BASE = 'https://api.github.com';
const TOKEN = process.env.GITHUB_TOKEN;  // optional for public repos

// GET /repos/{owner}/{repo}/issues?state=open&per_page=5
const owner = 'facebook';
const repo  = 'react';

// Build query string from an object (cleaner than manual string)
const params = new URLSearchParams({
    state:    'open',
    sort:     'created',
    per_page: '5',
});

const url = `${BASE}/repos/${owner}/${repo}/issues?${params}`;
console.log('URL:', url);
// → https://api.github.com/repos/facebook/react/issues?state=open&sort=created&per_page=5

const res = await fetch(url, {
    headers: {
        'Accept':        'application/vnd.github+json',
        'Authorization': TOKEN ? `Bearer ${TOKEN}` : undefined,
    },
});

if (!res.ok) {
    const err = await res.json().catch(() => ({ message: res.statusText }));
    throw new Error(`GitHub API ${res.status}: ${err.message}`);
}

const issues = await res.json();
console.log(`Found ${issues.length} open issues`);
issues.forEach(i => console.log(`  #${i.number}: ${i.title}`));

// Check rate limit from response headers
console.log('Remaining requests:', res.headers.get('x-ratelimit-remaining'));
console.log('Resets at:', new Date(res.headers.get('x-ratelimit-reset') * 1000));
